+      additionalProperties: false,
+    },
+  },
+  {
+    name: 'get',
+    description: 'Retrieve metadata for a single artifact by id.',
+    inputSchema: {
+      type: 'object',
+      properties: { id: { type: 'string' } },
+      required: ['id'],
