+      properties: { id: { type: 'string' } },
+      required: ['id'],
+      additionalProperties: false,
+    },
+  },
+  {
+    name: 'scaffold',
+    description: 'Scaffold a new artifact stub of a given type; returns the created path.',
+    inputSchema: {
+      type: 'object',
+      properties: { type: { type: 'string' }, path: { type: 'string' } },
+      required: ['type', 'path'],
+      additionalProperties: false,
+    },
+  },
